ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_plan_5"] = {
{"fw_ld5_milplan_e038","plan",2,"reg=military|day=2,20|mood=calm",{1,"Last radio check, Second Platoon was at the water tower",2,"That was Friday",1,"It's what we got, we go to the water tower, we find 'em, or we find what's left of the tower",2,"First light?",1,"First light, and I'm bringing the good coffee"}},
{"fw_ld5_milplan_e039","plan",2,"reg=military|day=2,30|mood=calm",{1,"Humvee's got an eighth of a tank",2,"There's fifty-fives at the motor pool, drums, that's the fuel",1,"Motor pool's two miles back through the wire",2,"We walk out, siphon what we can, then drive back like we own the road"}},
{"fw_ld5_milplan_e040","plan",2,"reg=military|mood=calm",{1,"Supply depot on Knox has pallets of MREs, I saw 'em stacked to the ceiling",2,"Depot's behind the second wire",1,"Second wire's where they stopped letting people through",2,"We find another way, the drainage culvert, I know it from a training exercise"}},
{"fw_ld5_milplan_e041","plan",2,"reg=military|mood=calm",{1,"I remember towing a water buffalo at the motor pool. Four hundred gallons when it was full",2,"That's a lot of water to move",1,"Drove one in the Gulf. I can talk about that, not promise there's one waiting for us",2,"If we ever find one, check the tank and the water before anybody starts celebrating"}},
{"fw_ld5_milplan_e042","plan",2,"reg=military|day=1,14|hour=6,17|mood=calm",{1,"We need sandbags, two hundred, we fill 'em at the quarry",2,"Two hundred? That's a day's work",1,"We start now, I want a wall by dark",2,"A wall means we sleep"}},
{"fw_ld5_milplan_e043","plan",2,"reg=military|mood=grim",{1,"Twelve rounds, that's what I got left, twelve",2,"I got fifteen",1,"So we got twenty-seven rounds for ten men",2,"We don't fire unless we have to, and we don't have to as long as we're quiet"}},
{"fw_ld5_milplan_e044","plan",2,"reg=military|day=2,30|hour=19,4|mood=calm",{1,"We move at night, no lights, I got one set of goggles for the lead",2,"One pair for ten guys",1,"One pair, the lead wears 'em, everybody else holds the belt of the man in front",2,"It's blind man's bluff, I hate it, but I get it"}},
{"fw_ld5_milplan_e045","plan",2,"reg=military|day=1,14|mood=funny",{1,"Our medic was a cook, so I'm the medic NOW",2,"Since when?",1,"Since the cook found a first aid book, I got a flashlight, a manual",2,"God help whoever gets hurt"}},
{"fw_ld5_milplan_e046","plan",2,"reg=military|day=3,30|mood=sad",{1,"I, I wanna go home",2,"We all wanna go home, Reyes",1,"Where's home? Knox is locked, and Ohio's three hundred miles",2,"...Then home's the next hill, and then the one after that, we find a hill with a house on it"}},
{"fw_ld5_milplan_e047","plan",2,"reg=military|day=2,30|mood=calm",{1,"Patrol goes out at oh-six-hundred, back by noon, I want everybody's boots dry",2,"Our boots haven't been dry since the Fourth",1,"Then I want 'em less wet, and I want everyone's rifle clean",2,"Roger, wet boots, clean rifles, Hatch, you're a poet"}},
{"fw_ld5_milplan_e048","plan",2,"reg=military|day=3,30|mood=calm",{1,"We got a map that's eight years old",2,"A map's a map",1,"Eight years ago that road wasn't there, and that building was",2,"So the map for the roads and our eyes for everything else"}},
{"fw_ld5_milplan_e049","plan",2,"reg=military|day=2,30|mood=calm",{1,"Chow's at six, I got oatmeal, half a jar of jelly, I'm not sharing the jelly",2,"The jelly's for the sergeant",1,"The sergeant's got a bad stomach, he can't have jelly, it's mine",2,"Selfish, but I'd do the same"}},
{"fw_ld5_milplan_e050","plan",2,"reg=military|mood=calm",{1,"We take the civilians with us if they want to come",2,"We got orders, and orders say nothing about civilians",1,"The orders say nothing, so we use our heads, I'm not leaving them",2,"We take 'em, I'll carry the little one on my shoulders"}},
{"fw_ld5_milplan_e051","plan",2,"reg=military|day=1,14|mood=grim",{1,"Report to the captain by dawn, he's at the school",2,"If the captain's still there",1,"He's there, I talked to him on the radio Sunday, then it went to static",2,"Sunday! Then that's three days, I'm not sure that's worth going for"}},
{"fw_ld5_milplan_e052","plan",2,"reg=military|day=2,30|mood=angry",{1,"Who's got the keys to the armory?",2,"The lieutenant, who's missing, shit",1,"Then we break it",2,"You break an Army armory, I'm NOT breaking it",1,"Then I'll break the damn thing, and you can write me up in a report nobody reads"}},
{"fw_ld5_milplan_e053","plan",2,"reg=military|day=3,40|mood=calm",{1,"Water's low, we got a creek, I can purify it with the tablets",2,"How many tablets?",1,"Forty, enough for about two weeks if we're careful",2,"Two weeks, then we find another creek, another box of tablets"}},
{"fw_ld5_milplan_e054","plan",2,"reg=military|mood=calm",{1,"You got a plan for tomorrow?",2,"Move at first light, take the high ground, wait for orders",1,"What if there are no orders?",2,"We wait, we eat, we think of a plan, I got nothing else"}},
{"fw_ld5_milplan_e055","plan",2,"reg=military|day=1,14|mood=fear",{1,"They, they said hold the line, I'm holding the line, there's nothing on the line",2,"Maybe nothing's coming",1,"Nothing on the line means there's something behind it, and I don't like it, not one damn bit",2,"...I'll take the first watch, you sleep, we both think about it in the morning"}},
{"fw_ld5_eliplan_e056","plan",2,"reg=elite|mood=calm",{1,"We go at oh-four-hundred, no comms",2,"Understood",1,"Package is at the bridge, I want eyes before we touch it",2,"Two up, two back, I'll take the left"}},
{"fw_ld5_eliplan_e057","plan",2,"reg=elite|mood=calm",{1,"We don't stop for civilians",2,"We stop for water",1,"If it's water, we stop. If it's civilians, keep moving",2,"Yeah. Your rule. I'm following it, that don't make it mine"}},
{"fw_ld5_eliplan_e058","plan",2,"reg=elite|mood=grim",{1,"Local police are asking questions",2,"Let 'em ask",1,"They'll want to know who we are",2,"We're not here, that's our answer"}},
{"fw_ld5_eliplan_e059","plan",2,"reg=elite|day=2,30|hour=19,5|mood=calm",{1,"Go dark, no fire, no talking",2,"Even whispers?",1,"Hand signals, you know 'em, I know you know 'em",2,"Copy, quiet, I live for quiet"}},
{"fw_ld5_eliplan_e060","plan",2,"reg=elite|mood=calm",{1,"Route is the tracks, stay off the road",2,"Tracks are slower",1,"Tracks are quieter, and nobody's watching tracks",2,"Then tracks it is"}},
{"fw_ld5_eliplan_e061","plan",2,"reg=elite|day=3,30|mood=funny",{1,"I'm hungry",2,"Eat",1,"I ate yesterday",2,"Eat again, then we move at first light, I'm not carrying you"}},
{"fw_ld5_eliplan_e062","plan",2,"reg=elite|mood=calm",{1,"We keep the group small, four, no more",2,"Why four?",1,"Four's quiet, five somebody coughs",2,"Four, understood, I'd have said three, but I'll take four"}},
{"fw_ld5_eliplan_e063","plan",2,"reg=elite|day=3,30|mood=grim",{1,"If one of us goes down, the rest don't stop",2,"That's the standing order?",1,"That's the order, I want it said before anybody argues",2,"Heard, and for the record, I'll argue anyway"}},
{"fw_ld5_lawplan_e064","plan",2,"reg=law,swat|mood=funny",{1,"I'm deputizing anybody with a pulse and a gun",2,"You can't do that",1,"Watch me, raise your right hand, congratulations, you're a deputy",2,"...Does it come with a badge?",1,"It comes with a flashlight and a lot of responsibility"}},
{"fw_ld5_lawplan_e065","plan",2,"reg=law,swat|mood=calm",{1,"Buses at the high school, six of 'em, keys on the board in the garage",2,"You wanna load 'em?",1,"I wanna load 'em with the church people, the old folks first, then whoever's left",2,"Then somebody's driving, and it's gonna be me, I got a license, I think it's still good"}},
{"fw_ld5_lawplan_e066","plan",2,"reg=law|day=1,14|mood=sad",{1,"Rex hasn't eaten since Sunday, he keeps looking at me",2,"The dog?",1,"He's a K-9, he's got four years on the job, I'm not leaving him in the kennel",2,"Then he rides with us, and he eats first, I'll find the dog food, I'll find a whole bag"}},
{"fw_ld5_lawplan_e067","plan",2,"reg=law,swat|mood=calm",{1,"Impound lot's got forty cars, half of 'em with gas, nobody's claiming 'em",2,"Keys?",1,"Every key's on a tag in the lot office, it's the most organized place in the county",2,"Then we take what we need, and for once nobody's gonna fight us about the paperwork"}},
{"fw_ld5_lawplan_e068","plan",2,"reg=law|day=2,30|mood=calm",{1,"We tack a notice on the courthouse door, church basement, noon, survivors welcome",2,"Who's gonna see it?",1,"Whoever comes by, there's always somebody who comes by, a paper on a door's a signal",2,"Print it big, and put your name on it, Hatcher, it's your signature that makes it official"}},
{"fw_ld5_lawplan_e069","plan",2,"reg=law|day=3,30|mood=sad",{1,"My mother's in Elizabethtown, I wanna go see her",2,"It's twenty miles",1,"I know how far it is, I'd be gone two days, you'd be short a man",2,"...Go, take the cruiser, I'll cover, and come back with her, bring her here, we'll make room"}},
{"fw_ld5_lawplan_e070","plan",2,"reg=law,swat|day=1,14|mood=calm",{1,"We don't set roadblocks, we help people through",2,"Through to where?",1,"To wherever's open, I'm not turning anybody around, I'm sick of being the guy who says no",2,"Then I'm sick of it too, we stand at the corner, we point"}},
{"fw_ld5_lawplan_e071","plan",2,"reg=law|mood=funny",{1,"I'm shaving",2,"What for?",1,"I look like a hobo, and I want the old man at the church to recognize me",2,"He'll recognize you, you're the only one in the county who still wears a tie"}},
{"fw_ld5_lawplan_e072","plan",2,"reg=law,swat|day=2,30|mood=calm",{1,"Resource officer at the school, Danny, he'd know every room",2,"If he's alive",1,"He's alive, I'd bet my pension, he's the kind that hides in the boiler room with a flashlight",2,"We find Danny first, the school after"}},
{"fw_ld5_lawplan_e073","plan",2,"reg=law,swat|day=2,30|mood=calm",{1,"Radio the Guard on the hour, every hour, even if nobody answers",2,"Four days nobody's answered",1,"Then the fifth day somebody will, that's what I figure, you keep trying",2,"I'll set the alarm on my watch, I'll do it till my batteries die"}},
{"fw_ld5_lawplan_e074","plan",2,"reg=law|day=3,30|mood=grim",{1,"The nursing home. Forty residents, and I haven't been there since Friday. It's on my list, I just... haven't been",2,"You want to go now?",1,"I should've gone already. I keep finding excuses because I'm scared of what's in there",2,"Then I'm coming with you. We go now. Whatever's in there, we talk about it after we're out"}},
{"fw_ld5_lawplan_e075","plan",2,"reg=law,swat|day=1,14|hour=18,4|mood=fear",{1,"If we shelter in a station, don't assume the building keeps us safe",2,"You're scaring the rookies",1,"I'd want them checking the exits. A steel cell door could keep us in as well as keep something out",2,"Sleeping in jail was never on the list of things I wanted to tell my kids"}},
{"fw_ld5_lawplan_e076","plan",2,"reg=law|day=2,30|mood=angry",{1,"Somebody stole the goddamn cruiser, I was inside for two minutes",2,"Who?",1,"Looked like a kid, fifteen, maybe, drove off with the lights on",2,"Then he's got a full tank and a bad idea, I'll find him, I'll walk him back by the ear"}},
{"fw_ld5_lawplan_e077","plan",2,"reg=law,swat|day=3,30|hour=6,17|mood=calm",{1,"Tow truck at Bobby's garage, we hitch the cruiser, we pull the van of the church ladies",2,"Why do we need a tow truck?",1,"The van's dead, forty ladies, one van, no gas, I want 'em in the church by dark",2,"Tow truck, forty ladies, that's the best sentence I've said all week"}},
{"fw_ld5_swatplan_e078","plan",2,"reg=swat|day=1,14|mood=calm",{1,"We wear the riot gear, helmets, shin guards, the thick vests, nothing bites through that",2,"It's July",1,"It's July, and I'm wearing the whole kit, if you're cold, you're doing it wrong",2,"I'll wear it, I'll sweat, I'll love it"}},
{"fw_ld5_swatplan_e079","plan",2,"reg=swat|mood=calm",{1,"We need a ladder, twenty feet, the roof of the pharmacy's our best view",2,"Where do we get a ladder?",1,"The fire station, or a house with a long one in the garage, I know a guy",2,"You always know a guy"}},
{"fw_ld5_swatplan_e080","plan",2,"reg=swat|day=3,30|mood=grim",{1,"The armored truck's still at the station, we can use it",2,"She still turn over?",1,"I started it last night, ran for ten minutes, then coughed, I think it wants a new filter",2,"Then we go find a filter, and I'm bringing a wrench, a big one"}},
{"fw_ld5_swatplan_e081","plan",2,"reg=swat|hour=19,5|mood=calm",{1,"We hit the church at four in the morning",2,"Why four?",1,"Because everyone's asleep, and nobody expects a team at four",2,"Four, I'll be up, I'll have coffee, I'll have a lot of coffee"}},
{"fw_ld5_swatplan_e082","plan",2,"reg=swat|mood=funny",{1,"What's a good name for our truck?",2,"It's an armored truck",1,"It needs a name, I'm thinking Betsy",2,"Betsy? ...Fine, Betsy takes the lead tomorrow, you tell her yourself"}},
{"fw_ld5_milplan_e083","plan",2,"reg=military|mood=calm",{1,"Check the guard post at the bridge, two men, four-hour shifts, someone's always awake",2,"That's eight guys for one bridge",1,"It's the only bridge we got, Reyes, I'm not trading it for a nap",2,"Roger, I'll take the first four"}},
{"fw_ld5_milplan_e084","plan",2,"reg=military|mood=calm",{1,"Convoy's five trucks, lead and trail with guns, the rest haul civilians, gas",2,"Speed?",1,"Twenty-five, and nobody passes, nobody stops, if a truck breaks down it gets towed",2,"Copy, and if the tow breaks?",1,"Then we make the tow break the tow, I don't know, I'm tired"}},
{"fw_ld5_milplan_e085","plan",2,"reg=military|mood=funny",{1,"Dig the latrine downwind",2,"Downwind of what?",1,"Of everything, Hatch, I don't wanna be the guy who put the latrine upwind",2,"Hooah, downwind, I'll go find a shovel"}},
{"fw_ld5_milplan_e086","plan",2,"reg=military|mood=calm",{1,"Radio relay on the hill, we put a man up there with a battery set, he calls us on the hour",2,"Boring job",1,"Boring job that keeps us alive, you wanna do it?",2,"I'm bad at boring, give it to Washington, he reads a lot"}},
{"fw_ld5_milplan_e087","plan",2,"reg=military|day=2,30|mood=funny",{1,"We're lost",2,"We're not lost",1,"We don't know where we are",2,"We know exactly where we are, we're in Kentucky, pick a road, we walk it"}},
{"fw_ld5_milplan_e088","plan",2,"reg=military|day=3,40|mood=sad",{1,"My-- my mom writes me every week, I got seventeen letters at the base I never opened",2,"Why not?",1,"Because if I open 'em, there's a last one, I'd know when",2,"...Keep 'em, open one a day, you never know, there might be more"}},
{"fw_ld5_milplan_e089","plan",2,"reg=military|mood=calm",{1,"MPs hold the line, nobody passes without a reason",2,"What the hell's a reason?",1,"A reason's a sick kid, a bad leg, a dog that needs a vet, anything with a face",2,"Then let 'em through, I'm not gonna ask for a pass from a man with a kid on his back"}},
{"fw_ld5_milplan_e090","plan",2,"reg=military|mood=grim",{1,"Litter for the wounded, two poles and a blanket, four men",2,"We got three",1,"Then three guys and a woman from the church, it's what we got, I don't care about regulation",2,"Move, I'll take the front, tell the woman to watch her step"}},
{"fw_ld5_milplan_e091","plan",2,"reg=military|day=3,30|mood=calm",{1,"We dig in at the crossroads, foxholes, a berm, a fire lane",2,"Till when?",1,"Till someone tells us otherwise, or till the shovels break",2,"Then we start digging, I'm not letting a shovel be the reason we leave"}},
{"fw_ld5_milplan_e092","plan",2,"reg=military|mood=angry",{1,"Somebody ate the cook's last tin of peaches",2,"Wasn't me",1,"It was somebody, I'm gonna find out, I'm gonna make 'em dig a latrine",2,"Then I confess, it was Washington, I watched him do it"}},
{"fw_ld5_milplan_e093","plan",2,"reg=military|day=1,14|mood=fear",{1,"Orders were clear, hold, I'm holding, but the line's gone",2,"Which line?",1,"All of 'em, there's nothing left to hold, I'm standing in a field holding a rifle",2,"We make a new line, we pick a hill, we say it's the line"}},
{"fw_ld5_milplan_e094","plan",2,"reg=military|mood=warm",{1,"You're a good shot",2,"I grew up hunting squirrels and deer",1,"Then you're on the roof tonight, north corner, I'll bring coffee up around two",2,"North corner's right, things come out of the trees on that side, same as deer"}},
{"fw_ld5_eliplan_e095","plan",2,"reg=elite|day=2,30|mood=calm",{1,"Let's take a look on foot. If it looks bad, we come back",2,"What if they see us?",1,"We leave. Looking isn't worth getting killed over",2,"All right. You lose sight of me, call me back"}},
{"fw_ld5_eliplan_e096","plan",2,"reg=elite|mood=calm",{1,"Extract the package, then move",2,"What's in the package?",1,"Not our business",2,"It's never our business, that's why they pay us"}},
{"fw_ld5_eliplan_e097","plan",2,"reg=elite|mood=calm",{1,"Nobody uses names or ranks out here, we're just the team",2,"That's a lot of rules",1,"It's worked so far",2,"Fine, but I'm calling you Frank in my head"}},
{"fw_ld5_eliplan_e098","plan",2,"reg=elite|mood=calm",{1,"Old railroad, three miles, we walk it at night",2,"Tracks don't lie",1,"They don't, and they don't have patrols",2,"Good, I like a straight line"}},
{"fw_ld5_eliplan_e099","plan",2,"reg=elite|day=3,30|mood=calm",{1,"We split, two and two, meet at the river by dawn",2,"What if one pair doesn't make it?",1,"The other pair keeps going, nobody turns back",2,"Understood, I'll be on time"}},
{"fw_ld5_crew_f001","plan",2,"reg=raider|day=1,30|mood=funny",{1,"Everybody's saying Kroger, every dumbass in the county's gonna be at the goddamn Kroger",2,"So?",1,"So we hit the little grocery on Elm, the one with the good stockroom",2,"Nobody thinks of it 'cause there's nothing in it, genius",1,"There's cigarettes, you fucking moron, a whole wall of 'em",2,"...Okay, that's different, why didn't you say cigarettes"}},
{"fw_ld5_crew_f002","plan",2,"reg=raider|mood=calm",{1,"Liquor store on Third, bourbon's worth more than ammo now, watch",2,"Bourbon's worth more than a woman's love, I heard",1,"It's worth more than YOUR woman's love, shut the fuck up, get in the truck",2,"...I don't have a woman, that's my point",1,"Then you got nothing to lose, drive"}},
{"fw_ld5_crew_f003","plan",2,"reg=raider|mood=calm",{1,"Pharmacy's got pills, not for us, for trading, folks'll hand over a rifle for the right bottle",2,"What's the right bottle?",1,"Name nobody can spell, label says don't take with alcohol",2,"Fuck the label, I got the liquor store, you got the pharmacy, we both got a goddamn truck"}},
{"fw_ld5_crew_f004","plan",2,"reg=raider|mood=grim",{1,"Church pantry's got forty cans, easy, we just walk right in and--",2,"No",1,"No what?",2,"I-- I ain't robbing a church, my mama's in that church, or she was, I don't know",1,"...Shit, fine, skip the church, we eat what we find",2,"Thank you, I mean it"}},
{"fw_ld5_crew_f005","plan",2,"reg=raider|mood=angry",{1,"Who the hell took the truck?",2,"Dax did, he went to the pawn shop, fuck",1,"Alone? That dumb son of a bitch'll get himself killed and take the truck with him",2,"So we go get him, and I get to say I told you so before I punch him",1,"Not till we got the truck back, then you can have him, damn it"}},
{"fw_ld5_crew_f006","plan",2,"reg=raider|day=2,30|mood=calm",{1,"We don't get greedy, we take what we can carry, ten minutes max",2,"Ten minutes, that's tight",1,"Ten minutes or we leave it, I seen what happens when you stay for one more shelf",2,"Buck stayed for a case of beer, never got Buck back",1,"Buck was a dumbass, God rest him"}},
{"fw_ld5_crew_f007","plan",2,"reg=raider|day=3,30|mood=funny",{1,"Truck stop's got diesel, a whole fuckin' tank",2,"We don't have a diesel truck",1,"We got a bike, a pickup, and a Buick, none of 'em run on diesel",2,"We trade the diesel, you idiot, it's the same fucking thing as money"}},
{"fw_ld5_crew_f008","plan",2,"reg=raider|mood=calm",{1,"Hobbs's used to keep rifles in the back. Used to daydream about their safe",2,"You'd want somebody who could open it",1,"You saying you could open one?",2,"I can open a beer. Give me time, I'll learn the rest",1,"Jesus Christ. Let's not make a plan out of your beer skills"}},
{"fw_ld5_crew_f009","plan",2,"reg=raider|mood=calm",{1,"Boss wants smokes, a lot of 'em",2,"What kind?",1,"Any kind, he's not picky when he's out, never seen a man so goddamn crazy for tobacco",2,"Warehouse on the tracks has cartons stacked to the ceiling, I seen it from the road"}},
{"fw_ld5_crew_f010","plan",2,"reg=raider|mood=calm",{1,"We take the church van, nobody'd think twice",2,"A church van, we look like we're going to a baptism",1,"That's the idea, nobody shoots a church van",2,"Somebody shoots anything, but I like it, it's funny",1,"Put your seatbelt on, deacon"}},
{"fw_ld5_crew_f011","plan",2,"r1=raider|r2=gang|mood=calm",{1,"Your guys and my guys, we split the take down the middle",2,"Half? That's too generous, what's the catch?",1,"No catch, half's what I'm offering, take it or hit the next store alone",2,"...Half, fine, but I get first pick of the fucking cigarettes"}},
{"fw_ld5_crew_f012","plan",2,"r1=raider|r2=club|day=2,30|mood=calm",{1,"You got bikes, we got a truck, we hit the gas station on the bypass together",2,"What the hell's in it for us?",1,"Gas, a whole tank, pour what you can carry",2,"Hell",2,"bikes need gas, and I like not walking, deal"}},
{"fw_ld5_crew_f013","plan",2,"r1=club|r2=raider|mood=funny",{1,"My club's got a prospect who can't ride, he keeps dumping the goddamn bike",2,"Sounds like a good prospect, honestly",1,"He's the best I got, so we take him to the hardware store, let him carry something heavy",2,"That's the kind of plan I like, a man learning to carry"}},
{"fw_ld5_crew_f014","plan",2,"r1=raider|r2=crime|day=2,30|mood=calm",{1,"The boss's cousin has a warehouse in Valley Station, he says it's full",2,"Full of what?",1,"Boxes, he won't say, he says it's worth the walk",2,"Boxes, that's it? I ain't walking thirty fucking miles for boxes, tell your cousin to bring it here"}},
{"fw_ld5_crew_f015","plan",2,"reg=raider|hour=19,4|mood=calm",{1,"We hit it at night, nobody's watching a grocery at night",2,"Nobody's watching a grocery at all",1,"Exactly, that's why it's a good plan, I'm a genius",2,"You're a genius, and I'm your driver, which makes me smarter"}},
{"fw_ld5_crew_f016","plan",2,"reg=raider|mood=angry",{1,"We got nothing to eat, the boss says hit the farm",2,"The old guy's got a shotgun",1,"The old guy's eighty, he's got a shotgun, hens, a garden",2,"No, hens, yeah, the old man, no, even we got a line somewhere",1,"Even for us, fuck, okay, the hens"}},
{"fw_ld5_crew_f017","plan",2,"reg=raider|mood=funny",{1,"So what's the plan?",2,"Go in, get everything, come out",1,"That's the entire plan?",2,"It's a good plan, it's worked twenty years, why change it"}},
{"fw_ld5_crew_f018","plan",2,"reg=raider|day=1,30|mood=calm",{1,"Meet at the overpass, nobody's late, you're late, you walk home",2,"What if I get lost?",1,"You can't get lost, it's one road",2,"You underestimate me"}},
{"fw_ld5_crew_f019","plan",2,"reg=raider|mood=grim",{1,"There's a toll on the bridge now, somebody's charging, shit",2,"Charging what?",1,"Cans, ammo, whatever you got, I seen a guy pay with a lawn mower, fuck",2,"A lawn mower, shit, we take the toll guys, then the bridge is ours, we charge it ourselves"}},
{"fw_ld5_crew_f020","plan",2,"reg=raider|hour=9,23|mood=calm",{1,"Who the hell's driving tonight?",2,"Not me, I drove last time, I almost put it in a ditch",1,"You did put it in a ditch",2,"That's why I'm saying, somebody else drives, I'm riding in the back with the goddamn beer",1,"You're riding in the back with the beer 'cause I'm driving, asshole"}},
{"fw_ld5_crew_f021","plan",2,"reg=raider|mood=funny",{1,"I say we pretend to be deputies",2,"We don't have uniforms",1,"We got a cop car, a badge off a dead guy, a lot of confidence",2,"Confidence, yeah, that's what we got, that plus no brains"}},
{"fw_ld5_crew_f022","plan",2,"reg=raider|mood=grim",{1,"We take the clinic's supplies, bandages, the whole shelf, before somebody else does",2,"For us?",1,"For trade, for Bobby's arm, I don't give a shit, it's all worth something",2,"Fine, but if somebody's in there hurt we leave 'em be, no more than we have to"}},
{"fw_ld5_crew_f023","plan",2,"reg=raider|day=1,14|mood=fear",{1,"Cops are out, we STAY off Dixie, damn it",2,"Cops are out? In this shit?",1,"One car, two deputies, I seen 'em, they're collecting people, I don't wanna be collected",2,"Back way, through the fields, we don't take the truck"}},
{"fw_ld5_crew_f024","plan",2,"reg=raider|day=3,30|mood=calm",{1,"Remember being told to count the money?",2,"I counted cans instead",1,"How the hell many?",2,"Sixty-one, that time. And a jar of pickles I wasn't going to share"}},
{"fw_ld5_crew_f025","plan",2,"reg=raider|mood=funny",{1,"Boss says nobody smokes till we count the damn cartons",2,"Count 'em? How many are there?",1,"Eight hundred, give or take",2,"I can count to ten, then I lose interest, somebody else counts",1,"That's why you ain't the boss"}},
{"fw_ld5_crew_f026","plan",2,"reg=raider|mood=funny",{1,"We put on armbands, tell 'em we're the Red Cross",2,"What's the Red Cross?",1,"They help people, and nobody shoots 'em, you dumbass",2,"I'll wear the armband, I'll say I'm helping, then we take their stuff"}},
{"fw_ld5_crew_f027","plan",2,"reg=raider|mood=calm",{1,"Every car on the highway's got a glove box, maps, cash, a gun sometimes",2,"Dead people's glove boxes",1,"Dead people don't need cash, I'm just saying it's a good use of an afternoon",2,"It's a gross use of an afternoon, but I'm in, I need a map"}},
{"fw_ld5_crew_f028","plan",2,"reg=raider|mood=angry",{1,"We're out of gas, the Marathon's picked, what now?",2,"There's the farm",1,"Farmers got guns, and cows, and a lot of goddamn anger, I ain't hitting a farm",2,"Then we walk, and when we get tired we rob the next person we see"}},
{"fw_ld5_crew_f029","plan",2,"reg=raider|mood=calm",{1,"Bourbon for ammo, that's the trade",2,"Who the hell's trading?",1,"The church people, they got ammo they don't wanna use, they hate us less if we bring a bottle",2,"Hate us less, I like that, it's the first nice thing about this whole fucking world"}},
{"fw_ld5_crew_f030","plan",2,"reg=raider|mood=funny",{1,"You carry, you watch, you drive, I'm the brains",2,"Why the hell are you the brains?",1,"Because I thought of this, I get to be the brains",2,"That's NOT how brains work, but fine"}},
{"fw_ld5_crew_f031","plan",2,"reg=raider|day=1,14|mood=fear",{1,"Something's coming, I can feel it",2,"What?",1,"Hell, I don't know, something big, we need to be gone",2,"Gone where?!",1,"Anywhere that ain't here, pack the goddamn truck"}},
{"fw_ld5_crew_f032","plan",2,"reg=raider|mood=angry",{1,"That's mine, I saw it first",2,"You-- you saw it, I picked it up",1,"Seeing is first, picking is second, I'm taking it",2,"Split it, half and half, I'll cut it with a knife, I'm not fighting over a can of beans"}},
{"fw_ld5_gangplan_f033","plan",2,"reg=gang|day=1,20|mood=calm",{1,"Corner store on Fourth, we hit it before the east side does",2,"They're already looking at it",1,"Looking ain't taking, man, we go now, five of us, quiet",2,"Five's too many, three, the rest hold the street",1,"Three, fine, but I'm one of the three, I found it"}},
{"fw_ld5_gangplan_f034","plan",2,"reg=gang|mood=calm",{1,"The block's ours, nobody comes through without us knowing",2,"How the hell we gonna know?",1,"Kid on the stairs, kid on the roof, whistle if somebody's walking",2,"Kids? You're using kids?",1,"They're better at it than us, they don't get bored"}},
{"fw_ld5_gangplan_f035","plan",2,"reg=gang|day=2,30|mood=angry",{1,"Where's the cans? We had forty yesterday",2,"Somebody's been in the stash",1,"Somebody, who's somebody? I wanna know who ate my goddamn peaches",2,"...It was Darnell, he's in the back, he's hiding, he's full",1,"DARNELL! Get your ass out here!"}},
{"fw_ld5_gangplan_f036","plan",2,"reg=gang|hour=10,22|mood=calm",{1,"Pharmacy on Main's got what the older guys want, they pay in guns",2,"I like guns",1,"Everybody likes guns, that's why we go before somebody else does",2,"When?",1,"Tonight, no moon, I checked"}},
{"fw_ld5_gangplan_f037","plan",2,"reg=gang|mood=funny",{1,"We should have a name, a real one",2,"We got a name",1,"We got a name from before, I want one for now",2,"The Peach Eaters",1,"...Shit, I hate that it's good"}},
{"fw_ld5_gangplan_f038","plan",2,"reg=gang|mood=grim",{1,"I once saw a crew hang a sheet out a window to claim a whole building",2,"What was on the sheet?",1,"One word, MINE, in red paint",2,"I'd find another building. I'm not fighting for a damn sheet"}},
{"fw_ld5_gangplan_f039","plan",2,"reg=gang|hour=19,4|mood=calm",{1,"We move at night, the dark's our friend",2,"The dark's everybody's friend now",1,"So we move quiet in the dark, that's all I'm saying",2,"I'm saying it too, I got a flashlight with a red filter, it's a gift"}},
{"fw_ld5_gangplan_f040","plan",2,"reg=gang|mood=calm",{1,"Rule is nobody goes alone, nobody",2,"I went to the damn store alone",1,"And you got back with a bag of chips and a bruise, you don't count",2,"It was a good bag of chips"}},
{"fw_ld5_gangplan_f041","plan",2,"reg=gang|mood=calm",{1,"We need a leader, somebody who decides things",2,"You",1,"Me? I'm too young",2,"You're twenty-two, that's old enough, I'm following you, the rest will follow me"}},
{"fw_ld5_gangplan_f042","plan",2,"reg=gang|day=3,30|mood=grim",{1,"Starving here, getting shot at out there, I don't love either one, shit",2,"So which?",1,"We go, and we shoot back, I'd rather do something"}},
{"fw_ld5_clubplan_f043","plan",2,"reg=club|mood=calm",{1,"Gas for the bikes, we hit the goddamn station on the bypass, everybody pours what he can carry",2,"How the hell much is that?",1,"Half a tank each, maybe more, we ride out tomorrow",2,"Where?",1,"The lake, there's a cabin, the club's been using it for years"}},
{"fw_ld5_clubplan_f044","plan",2,"reg=club|day=2,30|mood=funny",{1,"Remember that prospect who kept dropping his bike?",2,"Had to learn somehow",1,"Six times in one week. I counted",2,"You wanted him on a little Honda, a good bike for a bad rider",1,"He'd have dropped that too, God love him"}},
{"fw_ld5_clubplan_f045","plan",2,"reg=club|day=2,30|mood=calm",{1,"We ride in a line, thirty feet apart, nobody passes the prez",2,"What if there's a wreck?",1,"You go around it, you don't stop, I mean it, not for shit",2,"Never stop, thirty feet, got it"}},
{"fw_ld5_clubplan_f046","plan",2,"reg=club|mood=calm",{1,"The clubhouse on the highway's got a bar, a back room, a cellar full of food",2,"Who's gonna guard it?",1,"We take turns, two a night, I put you with the prospect",2,"Great",2,"I'm babysitting, thanks a lot, brother"}},
{"fw_ld5_clubplan_f047","plan",2,"reg=club|day=2,30|mood=calm",{1,"There's a bike shop in town, parts, tires, chrome, we need chain",2,"Chain for the bikes, I hate walking",1,"Fifteen minutes, in and out, take what we need, leave the rest",2,"And if the owner's there?",1,"Then we pay him with a can of peaches, hell, that's fair"}},
{"fw_ld5_clubplan_f048","plan",2,"reg=club|day=3,30|mood=angry",{1,"Somebody siphoned my fucking tank",2,"Wasn't me",1,"It was SOMEBODY, some son of a bitch, I'm gonna find him",2,"Then you find him, and I'll find a funnel, we're all low"}},
{"fw_ld5_clubplan_f049","plan",2,"reg=club|day=2,30|hour=5,12|mood=calm",{1,"First thing in the morning we ride to the farm, check the old man's barn",2,"What's in the fucking barn?",1,"Hay, a tractor, a hundred feet of dry floor, we sleep in it",2,"A hundred feet of dry floor, I'd ride to Mexico for that"}},
{"fw_ld5_clubplan_f050","plan",2,"reg=club|mood=calm",{1,"Louisville's got a clubhouse, a big one, it's the brothers there I want",2,"Louisville's twenty-five miles",1,"Twenty-five on a bike is an hour, if the road's open",2,"It's never open, but I'll ride it"}},
{"fw_ld5_clubplan_f051","plan",2,"reg=club|mood=grim",{1,"We lost two on the ride, NOBODY says it, but we lost two, fuck",2,"I know, damn it",1,"We hold a ride for them, one, before we go anywhere",2,"We ride slow past the church, everybody takes their gloves off"}},
{"fw_ld5_clubplan_f052","plan",2,"reg=club|day=3,30|mood=calm",{1,"You want a drink? We got a case of beer from the bar",2,"Warm?",1,"Warm, but it's beer",2,"I'd take warm beer and a cold shower, in that order"}},
{"fw_ld5_clubplan_f053","plan",2,"reg=club|day=2,30|mood=funny",{1,"What do you do when the world ends?",2,"Ride",1,"And when the gas runs out?",2,"We push, and I tell the story of the day we had to push"}},
{"fw_ld5_crmplan_f054","plan",2,"reg=crime|mood=calm",{1,"If somebody wanted an inventory, would you tell them what was in your pockets?",2,"My pockets?",1,"They'd call it business. Like calling it that made it their business",2,"I'd want to know why they were asking before I wrote anything down"}},
{"fw_ld5_crmplan_f055","plan",2,"reg=crime|day=2,30|mood=calm",{1,"Our guy at the pharmacy still has the key",2,"Is he alive?",1,"I don't know, that's why we're going, if he's alive he's got a stock, if he's not we find the key in his pocket",2,"Ugly, but it works"}},
{"fw_ld5_crmplan_f056","plan",2,"reg=crime|day=3,30|mood=grim",{1,"Hell, nobody touches the church food",2,"Why not?",1,"Because I don't want to explain it to the boss, and because we're not animals",2,"Fine, but the next place we hit, I'm taking the first pick"}},
{"fw_ld5_crmplan_f057","plan",2,"reg=crime|mood=calm",{1,"We count the cans every night, Jimmy writes it down, every night",2,"Why every night?",1,"Because when it's low we know it's low, somebody notices, somebody does something",2,"It's a good system, I like it, it's almost like a real business"}},
{"fw_ld5_crmplan_f058","plan",2,"reg=crime|mood=calm",{1,"Mr. D wants a meeting, he's got an idea",2,"What's the idea?",1,"Take over the grocery, charge the people who come in, a can for a can",2,"A can for a can? That's charity!",1,"It's business with manners, I'll tell him you said that"}},
{"fw_ld5_crmplan_f059","plan",2,"reg=crime|day=2,30|mood=calm",{1,"No heroics, nobody plays the big man, you get in, you get what we need, you get out",2,"That's a very short plan",1,"The long ones got people killed, I like short",2,"Then I'll keep it short, I'm in, I'm out, I'm home"}},
{"fw_ld5_crmplan_f060","plan",2,"reg=crime|mood=funny",{1,"What do we do with all the cash?",2,"What cash?",1,"The cash in the vault, it's worthless now",2,"Use it as kindling, it's good for something, and when the paper runs out, we start on the books"}},
{"fw_ld5_jailplan_f061","plan",2,"reg=prison|mood=calm",{1,"First thing, we get out of these clothes, orange glows in the dark",2,"Where the hell do we get clothes?",1,"Any house, any closet, I don't give a shit if it's a dress, I ain't walking around looking like a goddamn pumpkin",2,"...A dress, I'd like to see that"}},
{"fw_ld5_jailplan_f062","plan",2,"reg=prison|day=1,14|mood=grim",{1,"We stay off the roads, we go through the fields at night",2,"Fields have farmers",1,"Farmers have shotguns, but they got other problems now, it's a risk, it's the best one we got",2,"I'd rather risk a farmer than the roads, and the roads are all cops",1,"Roads were all cops, there ain't no cops, there's just us, shit"}},
{"fw_ld5_jailplan_f063","plan",2,"reg=prison|mood=calm",{1,"Indiana's across the river, nobody knows us there",2,"Nobody knows us here either, there's no system anymore",1,"There's no system, but there's a memory, people remember faces",2,"So we go where nobody has a face, and we start fresh"}},
{"fw_ld5_jailplan_f064","plan",2,"reg=prison|day=2,30|mood=angry",{1,"Hell, we ain't going back, you hear me? I'd rather die out here",2,"Nobody's going back, there ain't a back",1,"There ain't a back, just forward, God I hate it",2,"Forward, then, quit your whining"}},
{"fw_ld5_jailplan_f065","plan",2,"reg=prison|mood=calm",{1,"My cousin's got a place in the hills, a cabin, no neighbors for miles",2,"How far?",1,"Forty miles, I know the way, I used to hunt there before the thing with the damn car",2,"Forty miles on foot, at night, in these shoes, I'm gonna fucking die before we get there"}},
{"fw_ld5_jailplan_f066","plan",2,"reg=prison|day=2,30|mood=funny",{1,"Best day of my life, and for everybody else it's the worst--",2,"Don't say that out loud",1,"I'm saying it quiet, I'm a free man, nobody's coming to get me",2,"You're a free man with no shoes, Eddie"}},
{"fw_ld5_jailplan_f067","plan",2,"reg=prison|mood=calm",{1,"We take the church van, nobody checks a church van",2,"Nobody's checking anything",1,"Exactly, we're the only ones who think there's a cop at the end of the road",2,"Habit, it takes a while to quit"}},
{"fw_ld5_jailplan_f068","plan",2,"reg=prison|day=2,30|mood=grim",{1,"The guards, the ones we left, what happened to them?",2,"I don't know, I didn't stay to find out",1,"Me neither, but I keep thinking about 'em",2,"Don't, think about shoes, think about food, think about not being there"}},
